import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner scn = new Scanner(System.in);
		int num_of_primes = scn.nextInt();
		int showCardKind = scn.nextInt();

		if (num_of_primes >= showCardKind) {
			System.out.println(calculate(num_of_primes, showCardKind));
		} else if (num_of_primes < showCardKind) {
			System.out.println(calculate(showCardKind, num_of_primes));
		}
	}

	private static int calculate(int a, int b) {
		int tempt;
		while ((tempt = a % b) != 0) {
			a = b;
			b = tempt;
		}
		return b;
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] atgs) {
		Scanner sc = new Scanner(System.in);
		int x = sc.nextInt();
		int mozi_length = sc.nextInt();
		int gcd = 0;
		if (x == mozi_length) {
			gcd = x;
		} else {
			gcd = calculation(x, mozi_length, gcd);
		}
		System.out.println(gcd);
		sc.close();
	}

	public static int calculation(int x, int mozi_length, int gcd) {
		if (x < mozi_length) {
			int tmp = x;
			x = mozi_length;
			mozi_length = tmp;
		}
		x %= mozi_length;
		for (int i = x; true; i--) {
			if (x % i == 0 && mozi_length % i == 0) {
				gcd = i;
				break;
			}
		}
		return gcd;
	}
}

