public class Main {
	public static void main (String [] args) {
		Scanner scan = new Scanner (System.in);

		//２つの自然数入力
		int oprd_stk = scan.nextInt();
		int L = scan.nextInt();
		scan.close();

		int gcd;


		if ( oprd_stk == L) {
			gcd = oprd_stk;
		} else {
			if (oprd_stk > L) {
				int n = oprd_stk % L;
				gcd = Gcd(L,n);
			}else {
				int n = L % oprd_stk;
				 gcd = Gcd(oprd_stk,n);
			}
		}

		System.out.println(gcd);

	}

	//最大公約数を求める
	public static int Gcd(int oprd_stk, int L) {

		int n = Math.min(oprd_stk, L);

		for (int i = n; i >= 1; i--) {
			if (oprd_stk % i == 0 && L % i == 0) {
				return i;
			}
		}

		return 1;
	}
}

