import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args) {
		try {
			final BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
			final String[] setSubStrInput = in.readLine().split(" ");
			in.close();

			final int game_times = Integer.parseInt(setSubStrInput[0]);
			final int greatCD = Integer.parseInt(setSubStrInput[1]);

			System.out.println(String.valueOf(euclidean(game_times, greatCD)));
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	public static int euclidean(final int game_times, final int greatCD) {
		int a = game_times<greatCD ? greatCD : game_times;
		int sideLengths = game_times<greatCD ? game_times : greatCD;
		int r = a % sideLengths;

		while (r != 0) {
			a = sideLengths;
			sideLengths = r;
			r = a % sideLengths;
		}

		return sideLengths;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;


class Main{
    //読み込みのテンプレ(stringオブジェクトまで)
    public static void main(String[] args) throws IOException{
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String string = reader.readLine();
        StringTokenizer token = new StringTokenizer(string," ");

        int rateCalc = Integer.parseInt((String)token.nextElement());
        int heightint = Integer.parseInt((String)token.nextElement());

        int answer = gcd(rateCalc,heightint);
        System.out.println(answer);
    }

    public static int gcd(int rateCalc,int heightint){

        int answer;

        if(rateCalc > heightint){

            while(rateCalc%heightint != 0 || heightint !=1){
                int x_1 = rateCalc;
                int y_1 = heightint;
                rateCalc = heightint;
                heightint = x_1 % heightint;

                if(heightint == 0){
                    heightint = y_1;
                    break;
                }
            }
            if(heightint == 1){
                answer = 1;
            }else{
                answer = heightint;
            }


        }else{
            int x_y = rateCalc;
            int y_x = heightint;

            rateCalc = y_x;
            heightint = x_y;

            while(rateCalc%heightint !=0 || heightint !=1){
                int x_1 = rateCalc;
                int y_1 = heightint;
                rateCalc = heightint;
                heightint = x_1 % heightint;
                if(heightint == 0){
                    heightint = y_1;
                    break;
                }
            }
            if(heightint == 1){
                answer = 1;
            }else{
                answer = heightint;
            }

        }
        return answer;
    }
}

