	public static void main(String[] args)throws IOException, NumberFormatException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder builder = new StringBuilder();

		while(true){
			String[] reader = br.readLine().split(" ");
			int num = Integer.parseInt(reader[0]);
			int take = Integer.parseInt(reader[1]);
			if( num==0 && take==0 ) break;

			int count = 0;
			for( int intYokogoukei=1 ; intYokogoukei<=num-2 ; intYokogoukei++ ){
				for( int mulCount=intYokogoukei+1 ; mulCount<=num-1 ; mulCount++ ){
					for( int k=mulCount+1 ; k<=num ; k++ ){
						if( intYokogoukei+mulCount+k==take ) count++;
					}
				}
			}

			builder.append(count).append("\n");
		}

		System.out.print(builder);
	}
}

import java.io.*;

class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        while(true) {
            String[] s_i = br.readLine().split(" ");
