            int cnt_TLE = Integer.parseInt(s_i[1]);
            if (lowerBorder == 0 && cnt_TLE == 0) {
                break;
            }
            int count = 0;
            for(int setAllCardsExist = 3;setAllCardsExist <= lowerBorder;setAllCardsExist++){
                for(int j = 2;j < setAllCardsExist;j++){
                    for(int isMinus = 1;isMinus < j;isMinus++){
                        if((setAllCardsExist + j + isMinus) == cnt_TLE){
                            count++;
                        }
                    }
                }
            }
            System.out.println(count);
        }
    }

}

