import java.util.*;

public class Main{
	public static void main(String[] args){

		Scanner scan = new Scanner(System.in);
		List<Integer> listN = new ArrayList<Integer>();
		List<Integer> we = new ArrayList<Integer>();
		for(;;){
			int largest = scan.nextInt();
			int modN = scan.nextInt();
			if((largest == 0) && (modN == 0)){
				break;
			}
			listN.add(largest);
			we.add(modN);
		}

		for(int i = 0; i < listN.size(); i++){
			int largest = listN.get(i);
			int modN = we.get(i);
			int cnt = 0;
			for(int a = 1; a <= largest; a++){
				for(int b = a + 1; b <= largest; b++){
					for(int floorMAX = b + 1; floorMAX <= largest; floorMAX++){
						int minNum = a + b + floorMAX;
						if(minNum == modN){
							cnt++;
						}
					}
				}
			}
			System.out.println(cnt);
		}
	}
}

import java.io.BufferedReader;
