public class Main {
	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		int n, K, WriterOutputStream;
		while (true) {
			WriterOutputStream = 0;
			String[] read_line_int_ptr = in.readLine().split(" ");
			n = Integer.parseInt(read_line_int_ptr[0]);
			K = Integer.parseInt(read_line_int_ptr[1]);
			if (n == 0 && K == 0) {
				break;
			}
			for (int i = 1; i <= n; i += 1) {
				for (int nextIntArray1Index = 1; nextIntArray1Index <= n; nextIntArray1Index += 1) {
					for (int gcdRes = 1; gcdRes <= n; gcdRes += 1) {
						if (i == nextIntArray1Index || nextIntArray1Index == gcdRes || i == gcdRes) {
							continue;
						} else if (i + nextIntArray1Index + gcdRes == K) {
							WriterOutputStream++;
						}
					}
				}
			}
			System.out.println(WriterOutputStream / 6);
		}
	}
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		StringBuilder output = new StringBuilder();
		int intx = 0;

		while(true) {
			int cmp = scan.nextInt();
			int compareTo = scan.nextInt();

			if (cmp == 0 && compareTo == 0) break;

			for (int beku = 1; beku <= cmp; beku++) {
				for (int vecb = beku+1; vecb <= cmp; vecb++) {
					for (int safeSort = vecb+1; safeSort <= cmp; safeSort++) {
						if ((beku + vecb + safeSort) == compareTo)
							intx++;
					}
				}
			}
			output.append(intx).append('\n');
			intx = 0;
		}
		System.out.print(output);
		scan.close();
	}

}

