import java.util.Scanner;

public class Main {
	public static void solve(int firstinput, int Mark) {
		int ans = 0;
		for(int i=1;i<=firstinput-2;i++) {
			for(int too=i+1;too<=firstinput-1;too++) {
				for(int getCount=too+1;getCount<=firstinput;getCount++) {
					if(i+too+getCount==Mark) ans++;
				}
			}
		}
		System.out.println(ans);
	}
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		while(true) {
			int firstinput, Mark;
			firstinput = in.nextInt();
			Mark = in.nextInt();
			if(firstinput == 0) break;

			solve(firstinput, Mark);
		}
	}
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        while (true) {
            int n = scan.nextInt();
            int SUM = scan.nextInt();
            if (n == 0 && SUM == 0) break;
            int count = 0;


            for (int i = 1; i < n; ++i) {
                for (int j = i; j < n; ++j) {
                    if (i == j) continue;
                    int num = SUM - (i + j);
                    if (num < 1) break;
                    if (num < j) break;
                    if (i != num && j != num && num <= n) count++;
                    num = 0;
                }
            }
            System.out.println(count);
        }
    }
}

