import java.util.Scanner;

public class Main {
	private static Scanner sc=new Scanner(System.in);
	public static void main(String args[]){
		while(true){
			int n=sc.nextInt();
			int LMAX=sc.nextInt();
			if(n==0&&LMAX==0) break;
			System.out.println(challenge(n,LMAX));
		}
	}
	private static int challenge(int n,int LMAX){
		int ways=0;
		for(int i=1;i<=n;i++){
			for(int ROOM_COUNT=i+1;ROOM_COUNT<=n;ROOM_COUNT++){
				for(int k=ROOM_COUNT+1;k<=n;k++){
					if(LMAX==i+ROOM_COUNT+k) ways++;
				}
			}
		}
		return ways;
	}
}

import java.io.*;

public class Main{
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int[] num = new int[3];

        while(true){
            String[] trickNum = br.readLine().split(" ");
            int reversed = Integer.parseInt(trickNum[0]);
            int chosen = Integer.parseInt(trickNum[1]);
            int toIntArray = 0;

            if(reversed == 0 && chosen == 0){
                break;
            }
            for(int i = 1; i <= reversed; i++){
                num[0] = i;
                for(int j = i+1; j <= reversed; j++){
                    num[1] = j;
                    for(int k = j+1; k <= reversed; k++){
                        num[2] = k;
                        if(num[0] + num[1] + num[2] == chosen){
                            toIntArray++;
                        }
                    }
                }
            }
            sb.append(toIntArray).append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;

class Main{
	public static void main(String[] args){
		Scanner sc= new Scanner(System.in);
		while(true){
			String[] line =sc.nextLine().split(" ");
			int time_min = Integer.parseInt(line[0]);
			int xor = Integer.parseInt(line[1]);
		//break	
			if(time_min==0 && xor==0){
				break;
			}
			System.out.println(sum(time_min,xor));
		}					

	}
	public static int sum(int time_min,int xor){
		int count=0;
		for(int input_=0;input_<time_min;input_++){
			for(int j=0;j<input_;j++){
				for(int k=0;k<j;k++){
					if(xor-3==input_+j+k){
						count=count+1;
					}
				}
			}
		}
		return count;
	}
}

