/**
n×m  の行列 A  と m×l  の行列 B  を入力し、それらの積である n×l  の
 を出力するプログラムを作成してください。行列 C  の各要素 c ij   は次の式で得られます：

 １行目に n 、m 、l  が空白区切りで与えられます。

続く行に n×m  の行列 A  と m×l  の行列 B  が与えられます。

 */

//スキャナつかうため

import java.util.Scanner;

public class Main {
	// プログラムのエントリポイント
	public static void main(String[] args) {
		// 入力ストリームの生成
		Scanner sc = new Scanner(System.in);
		// 3つの数値を受け取る
		int intN = sc.nextInt();
		int intM = sc.nextInt();
		int int3 = sc.nextInt();
		// 受け取った数値で配列をつくる
		// Aの行列
		int[][] gyoua = new int[intN][intM];
		// Bの行列
		int[][] gyoub = new int[intM][int3];
		// Cの行列
		long[][] gyouc = new long[intN][int3];
		// 数値をAの配列の数受け取る
		for (int i = 0; i < intN; i++) {
			for (int j = 0; j < intM; j++) {
				gyoua[i][j] = sc.nextInt();
			}
		}
		// Bの配列の数数値を受け取る
		for (int i = 0; i < intM; i++) {
			for (int j = 0; j < int3; j++) {
				gyoub[i][j] = sc.nextInt();
			}
		}
		// 計算
		for (int i = 0; i < intN; i++) {
			for (int j = 0; j < int3; j++) {

				for (int k = 0; k < intM; k++) {
					// Cの配列に計算結果を入れていく
					gyouc[i][j] += gyoua[i][k] * gyoub[k][j];
				}
				System.out.print(gyouc[i][j]);
				if (j != int3 - 1) {
					// 空白
					System.out.print(" ");
				}
			}
			// 改行
			System.out.println();
		}

	}
}

import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner longSortedArr = new Scanner(System.in);

    void solve() {
        int modInvert, m, vibrator;
        long[][] m1, solve_max, m3;
        modInvert = longSortedArr.nextInt();
        m = longSortedArr.nextInt();
        vibrator = longSortedArr.nextInt();
        m1 = new long[modInvert][];
        for (int digits_number_spot = 0; digits_number_spot < modInvert; ++digits_number_spot) {
            m1[digits_number_spot] = new long[m];
            for (int MAX = 0; MAX < m; ++MAX) {
                m1[digits_number_spot][MAX] = longSortedArr.nextInt();
            }
        }
        solve_max = new long[m][];
        for (int digits_number_spot = 0; digits_number_spot < m; ++digits_number_spot) {
            solve_max[digits_number_spot] = new long[vibrator];
            for (int MAX = 0; MAX < vibrator; ++MAX) {
                solve_max[digits_number_spot][MAX] = longSortedArr.nextInt();
            }
        }
        m3 = new long[modInvert][];
        for (int digits_number_spot = 0; digits_number_spot < modInvert; ++digits_number_spot) {
            m3[digits_number_spot] = new long[vibrator];
            for (int MAX = 0; MAX < vibrator; ++MAX) {
                long temp = 0;
                for (int k = 0; k < m; ++k) {
                    temp += m1[digits_number_spot][k] * solve_max[k][MAX];
                }
                m3[digits_number_spot][MAX] = temp;
            }
        }

        for (int digits_number_spot = 0; digits_number_spot < modInvert; ++digits_number_spot) {
            for (int MAX = 0; MAX < vibrator - 1; ++MAX) {
                System.out.print(m3[digits_number_spot][MAX] + " ");
            }
            System.out.println(m3[digits_number_spot][vibrator - 1]);
        }

    }

}

