public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int reCount = sc.nextInt();
		int TIME = sc.nextInt();

		int[][] WW = new int[n][reCount];
		int[][] NOT_FOUND = new int[reCount][TIME];

		for (int calculateGreatestCommonDivisor = 0; calculateGreatestCommonDivisor < n; calculateGreatestCommonDivisor++) {
			for (int j = 0; j < reCount; j++) {
				WW[calculateGreatestCommonDivisor][j] = sc.nextInt();
			}
		}

		for (int calculateGreatestCommonDivisor = 0; calculateGreatestCommonDivisor < reCount; calculateGreatestCommonDivisor++) {
			for (int j = 0; j < TIME; j++) {
				NOT_FOUND[calculateGreatestCommonDivisor][j] = sc.nextInt();
			}
		}
		sc.close();

		long[][] ALDS1_3_B_Process = new long[n][TIME];
		for (int calculateGreatestCommonDivisor = 0; calculateGreatestCommonDivisor < n; calculateGreatestCommonDivisor++) {
			for (int j = 0; j < TIME; j++) {

				long NEG = 0;
				for (int k = 0; k < reCount; k++) {
