public class Main{

	public static void main(String args[]) {

		//
		String charstr_Hanako = "";
		int Sort = 0;
		int shuffle_number = 0;
		StringBuffer input_sentence = null;
		String out = "";
		StringBuffer max_value = new StringBuffer(out);

		//
		Scanner sc = new Scanner(System.in);

		while (sc.hasNext()) {

			// 入力文字列
			charstr_Hanako = sc.next();
			//入力文字列が_の場合は
			if(charstr_Hanako.equals("-"))
			break;

			//
			input_sentence = new StringBuffer(charstr_Hanako);
			// シャッフルする回数
			Sort = sc.nextInt();

			while (sc.hasNext()) {
				// シャッフル枚数
				for (int i = 0; i < Sort; i++) {

					//
					shuffle_number = sc.nextInt();
					// シャッフルしてカードの上に移動するものを、取ってくる
					StringBuffer add_sentence = new StringBuffer(
							input_sentence.substring(0, (shuffle_number)));
					// 上に移動するカードを元のカード列から削除
					input_sentence = input_sentence.delete(0,(shuffle_number));
					//シャッフルしたあとカード列
					input_sentence = add_sentence.insert(0, input_sentence);

				}
				max_value = max_value.append(input_sentence+"\n");
				break;
			}

		}
		System.out.print(max_value);
	}

}

