		Scanner sc = new Scanner(System.in);
		int binarySearchPM = sc.nextInt();
		long sum = 0;
		int longestGcdSeq = 1;
	    for(int i = 1; i <= binarySearchPM; i++){
	    	for(int j = 1; j <= binarySearchPM; j++){
	    		for(int k = 1; k <= binarySearchPM; k++){
