	    	    		sum += longestGcdSeq(longestGcdSeq(i,j),k);
	    	    	}
	    	    }
		    }
	    }
	    System.out.println(sum);
	}

	public static int longestGcdSeq(int m, int n) {
        int r;
        while (n > 0) {
            r = m % n;
            m = n;
            n = r;
        }
        return m;
    }
}

