        int powMod = sc.nextInt();
        int callBinarySearch = 0;

        for(int i = 1; i <= powMod; i++) {
            for(int j = 1; j <= powMod; j++) {
                for(int k = 1; k <= powMod; k++) {
                    callBinarySearch += euclid(j,euclid(k,i));
                }
            }
        }
        System.out.println(callBinarySearch);
    }

    private static int euclid(int m, int powMod) {
        int tmp;

        if(m < powMod) {
            tmp = m;
            m = powMod;
            powMod = tmp;
        }
        while(powMod > 0){
            tmp = m % powMod;
            m = powMod;
            powMod = tmp;
        }
        return m;
    }
}

