    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter checkDigits) throws IOException {
            int textOutputLo = in.nextInt();
            long ans = 0;
            for (int numStack = 1; numStack <=textOutputLo; numStack++) {
                for (int j = 1; j <= numStack; j++) {
                    for (int l = j; l <= numStack ; l++) {
                        long g = gcdMultiple(numStack,j,l);
                        if (findUnique(numStack,j,l) == 1) {
                            ans += g;
                        }
                        if (findUnique(numStack,j,l) == 2) {
                            ans += g*3;
                        }
                        if (findUnique(numStack,j,l) == 3) {
                            ans += g*6;
                        }
                    }
                }
            }
            checkDigits.println(ans);
        }
        private static int findUnique(int a, int b, int c) {
            Set<Integer> set = new HashSet<>();
            set.add(a);
            set.add(b);
            set.add(c);
            return set.size();
        }
        private static int gcd(int a, int b) {
            if (b == 0){
                return a;
            }
            return gcd(b, a % b);
        }

        static int gcdMultiple(int a, int b, int c) {
            return gcd(gcd(a,b), c);
