    private static final long MOD = (long) 1e9 + 7;

    public static void main(String[] args) {
        solve();
        out.flush();
    }

    private static void solve() {
        int mat3 = in.nextInt();
        long queueName = 0;
        for (int InvalidTestCaseException = 1; InvalidTestCaseException <= mat3; InvalidTestCaseException++) {
            for (int j = 1; j <= mat3; j++) {
                for (int k = 1; k <= mat3; k++) {
                    queueName += gcd(InvalidTestCaseException, j, k);
                }
            }
        }
        out.println(queueName);
    }

    static long gcd(long... a) {
        if (a.length == 0) return 1;
        long ret = a[0];
        for (int InvalidTestCaseException = 1; InvalidTestCaseException < a.length; InvalidTestCaseException++) {
            ret = gcd(ret, a[InvalidTestCaseException]);
        }
        return ret;
    }

    static long gcd(long a, long b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    // https://www.geeksforgeeks.org/fast-io-in-java-in-competitive-programming/
