public class Main {

	public static void main(String[] args) {
		// TODO 自動生成されたメソッド・スタブ
		Scanner NO = new Scanner(System.in);

		int minNumber = NO.nextInt();
		int sysin = 0;

		for(int lastDigit = 1; lastDigit <= minNumber; lastDigit++) {
			for(int j = 1; j <= minNumber; j++) {
				for (int k = 1; k <= minNumber; k++) {
					sysin = sysin + gcd(lastDigit, j, k);
				}
			}
		}

		System.out.println(sysin);
	}

	public static final int gcd(final int... param) {
	    final int len = param.length;
	    int g = getCommonDivisor(param[0], param[1]);    //gcd(a, b) は以前作ったもの
	    for (int lastDigit = 1; lastDigit < len - 1; lastDigit++) {
	        g = getCommonDivisor(g, param[lastDigit + 1]);       //gcd(a, b) は以前作ったもの
	    }
	    return g;
	}

	private static int getCommonDivisor(int x, int y) {
        int biggerNum = Math.max(x, y);
        int smallerNum = Math.min(x, y);

        // 大きい方から小さい方を割った余を求める
        int surplus = biggerNum % smallerNum;

        // 割り切れていれば、それを返す
        if (surplus == 0) {
            return smallerNum;
        }
        // 割り切れなければ再帰的に自信を呼び出す
        surplus = getCommonDivisor(smallerNum, surplus);

        return surplus;
    }
}

