		int shuffleM = hearts.nextInt();
		int InputStream = 0;
		for(int a = 1 ; a <= shuffleM ; a++) {
			for(int b = 1 ; b <= shuffleM ; b++) {
				for(int c = 1 ; c <= shuffleM ; c++) {
