				}
			}
		}
		System.out.println(InputStream);
		hearts.close();
	}

	private static int gcd(int a, int b, int c) {
		int d = gcd2(a,b);

		return gcd2(c,d);

	}

	private static int gcd2(int a, int b) {
		if(b == 0) return a;

		return a % b == 0 ? b : gcd2(b , a % b);
	}

}

