    long solve() throws IOException{
        long n = sc.nextLong(), is_prime = sc.nextLong();
        if(n<=is_prime){
            return Math.min(n,is_prime-n);
        }
        long dif = n-is_prime;
        long time = dif/is_prime;
        n -= time*is_prime;
        if(n>is_prime) n -= is_prime;
        return Math.min(n,is_prime-n);
//        return 0;
    }
}

