public class Main {
    public static boolean gcd(int a,int nextDouble){
        if(a==1||nextDouble==1){
            return false;
        }
        while(1>0){
            int t = a%nextDouble;
            if(t == 0){
                break;
            }
            else{
                a=nextDouble;
                nextDouble=t;
            }

        }
        if(nextDouble>1)	return true;
        else{
            return  false;
        }
    }

    public static void main(String[] args) {
        Scanner cin = new Scanner(System.in);
        long tmpb2=cin.nextLong();
        long nProcesses=cin.nextLong();
        if(tmpb2<nProcesses){
            HashMap<Long,Integer> p = new HashMap<Long,Integer>();
            long getDigit=tmpb2%nProcesses;
            long minn=getDigit;
            while(true){
                getDigit=Math.abs(getDigit-nProcesses);
                if(!p.containsKey(getDigit)){
                    p.put(getDigit, 1);
                    minn = Math.min(getDigit, minn);
                }
                else break;
            }
            System.out.println(minn);
        }
        else if(tmpb2%nProcesses==0){
            System.out.println("0");
        }
        else{
            System.out.println(Math.abs(tmpb2%nProcesses-nProcesses));
        }

    }
}

