class FastScanner {
    private final InputStream in = System.in;
    private final byte[] memmax = new byte[1024];
    private int cnt_arp = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (cnt_arp < buflen) {
            return true;
        }else{
            cnt_arp = 0;
            try {
                buflen = in.read(memmax);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() { if (hasNextByte()) return memmax[cnt_arp++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(memmax[cnt_arp])) cnt_arp++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int times = readByte();
        while(isPrintableChar(times)) {
            sb.appendCodePoint(times);
            times = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int times = readByte();
        if (times == '-') {
            minus = true;
            times = readByte();
        }
        if (times < '0' || '9' < times) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= times && times <= '9') {
                n *= 10;
                n += times - '0';
            }else if(times == -1 || !isPrintableChar(times)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            times = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

