class Solver {
	static final Solver INSTANCE = new Solver();

	void solve(Scanner sc) {
		int input3 = sc.nextInt();
		String[] S = new String[input3];
		for (int i = 0; i < input3; i++) {
			S[i] = sc.next();
		}
		Arrays.sort(S);
		String current = "";
		int streak = 0;
		int max = 0;
		for (String s : S) {
			if (!s.equals(current)){
				max = Math.max(max, streak);
				streak = 1;
				current = s;
			} else {
				streak += 1;
			}
		}
		max = Math.max(max, streak);
		current = "";
		streak = 0;
		for (String s : S) {
			if (!s.equals(current)){
				if (streak == max){
					System.out.println(current);
				}
				streak = 1;
				current = s;
			} else {
				streak += 1;
			}
		}
		if (streak == max){
			System.out.println(current);
		}
	}
}

