import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner intKazu = new Scanner(System.in);
		int three = intKazu.nextInt();

		String S[] = new String[three];
		intKazu.nextLine();

		for (int i = 0; i < three; i++) {
			S[i] = intKazu.nextLine();
		}

		Arrays.sort(S);

		int cnt = 1;
		Map<String, Integer> map = new HashMap<>();

		for (int i = 0; i < three - 1; i++) {
			if (S[i].equals(S[i + 1])) {
				cnt++;
			} else {
				map.put(S[i], cnt);
				cnt = 1;
			}
		}

		if (S[three - 2].equals(S[three - 1])) {
			map.put(S[three - 1], cnt);
		} else {
			map.put(S[three - 2], cnt);
			map.put(S[three - 1], 1);
		}

		int maxcnt = 0;

		ArrayList<String> str = new ArrayList<>();

		for (String key : map.keySet()) {
			if (map.get(key) > maxcnt)
				maxcnt = map.get(key);
		}

		for (String key : map.keySet()) {
			if (map.get(key) == maxcnt)
				str.add(key);
		}

		Collections.sort(str);
		for (String s : str) {
			System.out.println(s);
		}

		intKazu.close();

	}
}

