                list.clear();
                list.add(entry.getKey());
                max = x;
            } else if (max == x) {
                list.add(entry.getKey());
            }
        }
        Collections.sort(list);
        StringBuilder sb = new StringBuilder();
        for (String s : list) {
            sb.append(s).append("\n");
        }
        System.out.print(sb);
    }
}

