        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter maxPrime = new PrintWriter(outputStream);
        ABC153_b solver = new ABC153_b();
        solver.solve(1, in, maxPrime);
        maxPrime.close();
    }

    static class ABC153_b {
        public void solve(int testNumber, Scanner in, PrintWriter maxPrime) {
            int team = in.nextInt();
            int ms = in.nextInt();
            int arr[] = new int[ms];

            for (int i = 0; i < ms; i++) {
                arr[i] = in.nextInt();
            }
            Arrays.sort(arr);
            for (int j = 0; j < ms; j++) {
                team -= arr[j];
                if (team <= 0) {
                    maxPrime.println("Yes");
                    return;
                }
            }
            maxPrime.println("No");
        }

    }
}

