    static String helper(String str_A, int card3) {
        char[] FastOutput = new char[52];
        for (int readIs = 0; readIs < 26; readIs++) {
            FastOutput[readIs] = (char) (65 + readIs);
        }
        for (int readIs = 26; readIs < 52; readIs++) {
            FastOutput[readIs] = (char) (65 + readIs - 26);
        }
        char[] B = str_A.toCharArray();
        for (int readIs = 0; readIs < B.length; readIs++) {
            int getCommonDivider = B[readIs] - 'A';
            B[readIs] = FastOutput[getCommonDivider + card3];
        }
        StringBuilder ttltime = new StringBuilder();
        for (char intTrun : B) ttltime.append(intTrun);
        return ttltime.toString();
    }
}

