import java.io.PrintWriter;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner strInput = new Scanner(System.in);
        int HOUR = Integer.parseInt(strInput.next());
        long intTempX = Long.parseLong(strInput.next());
        int deQueue = Integer.parseInt(strInput.next());

        int[] A = new int[deQueue];
        for (int i = 0; i < deQueue; i++) {
            A[i] = Integer.parseInt(strInput.next());
        }

        solve(HOUR, deQueue, intTempX, A);
    }

    public static void solve(int priceTmp, int cheaper, long k, int[] a) {
        long[] dp = new long[priceTmp];
        for (int i = 0; i < cheaper; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        PrintWriter out = new PrintWriter(System.out);
        for (long element : dp) {
            if (cheaper - k >= element)
                out.println("No");
            else
                out.println("Yes");
        }
        out.flush();
    }
}

