 */
public class Main
{
    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA
    {
        public void solve(int testNumber, Scanner in, PrintWriter out)
        {
            int mtx1 = in.nextInt();
            int[] r3 = new int[mtx1 + 1];
            int[] b = new int[mtx1 + 1];
            int[] c = new int[mtx1];

            //Dishes
            for (int i = 1; i <= mtx1; i++)
            {
                r3[i] = in.nextInt();
            }
            //Satisfactions
            for (int i = 1; i <= mtx1; i++)
            {
                b[i] = in.nextInt();
            }
            //C
            for (int i = 1; i < mtx1; i++)
            {
                c[i] = in.nextInt();
            }

            //Eating
            int sat = 0;

            sat += b[r3[1]];
            int lastEat = r3[1];

            for (int i = 2; i <= mtx1; i++)
            {
                sat += b[r3[i]];
                if (lastEat + 1 == r3[i])
                {
                    sat += c[r3[i - 1]];
                }
                lastEat = r3[i];
            }
            out.print(sat);
        }

    }
}

