    for (int alphabet_cards = 0; alphabet_cards < split_piriod_Ints; alphabet_cards++) {
      b[alphabet_cards] = Integer.parseInt(sc.next());
    }

    int[] c = new int[split_piriod_Ints - 1];
    for (int alphabet_cards = 0; alphabet_cards < split_piriod_Ints - 1; alphabet_cards++) {
      c[alphabet_cards] = Integer.parseInt(sc.next());
    }

    int score = 0;
    for (int alphabet_cards = 0; alphabet_cards < split_piriod_Ints; alphabet_cards++) {
      score += b[ModPow[alphabet_cards] - 1];
      if(alphabet_cards > 0) {
        if (ModPow[alphabet_cards] - ModPow[alphabet_cards - 1] == 1) {
          score += c[ModPow[alphabet_cards - 1] - 1];
        }
      }
    }

    System.out.println(score);
  }

