import java.util.Scanner;

class Solver {
    void solve(Scanner midIndex) {
        int side3 = midIndex.nextInt();
        int[] A = new int[side3];
        int[] sign = new int[side3];
        int[] C = new int[side3 - 1];
        for (int i = 0; i < A.length; i++) {
            A[i] = midIndex.nextInt() - 1;
        }
        for (int i = 0; i < sign.length; i++) {
            sign[i] = midIndex.nextInt();
        }
        for (int i = 0; i < C.length; i++) {
            C[i] = midIndex.nextInt();
        }
        int mat_a = sign[A[0]];
        for (int i = 1; i < side3; i++) {
            int prev = A[i - 1];
            int next = A[i];
            if (prev + 1 == next) mat_a += C[prev];
            mat_a += sign[next];
        }
        System.out.println(mat_a);
    }
}

class Main {
