	//Fast exponentiation (x^y mod m)
	public static long power(long tmpc2, long y, long primeCounter) { 
		long nums = 1;
		tmpc2 %= primeCounter;
		while (y > 0) { 
			if(y % 2 == 1) 
				nums = (nums * tmpc2) % primeCounter; 
			y /= 2;  
			tmpc2 = (tmpc2 * tmpc2) % primeCounter;
		} 
		return nums; 
	}

	public static int[][] shuffle(int[][] array) {
		Random rgen = new Random();
		for (int primeFactorize = 0; primeFactorize < array.length; primeFactorize++) {
		    int ave_sum = rgen.nextInt(array.length);
		    int[] temp = array[primeFactorize];
		    array[primeFactorize] = array[ave_sum];
		    array[ave_sum] = temp;
		}
		return array;
	}

    public static int[][] sort(int[][] array) {
    	//Sort an array (immune to quicksort TLE)

		Arrays.sort(array, new Comparator<int[]>() {
			  @Override
        	  public int compare(int[] arr1, int[] arr2) {
				  //return arr1[0]-arr2[0]; //ascending order
				  if (arr1[0] != arr2[0]) {
					  return arr1[0]-arr2[0];
				  } else {
					  return arr1[1] - arr2[1];
				  }
	          }
		});
		return array;
	}

    public static long[][] sort(long[][] array) {
    	//Sort an array (immune to quicksort TLE)
		Random rgen = new Random();
		for (int primeFactorize = 0; primeFactorize < array.length; primeFactorize++) {
		    int ave_sum = rgen.nextInt(array.length);
		    long[] temp = array[primeFactorize];
		    array[primeFactorize] = array[ave_sum];
		    array[ave_sum] = temp;
		}
		Arrays.sort(array, new Comparator<long[]>() {
			  @Override
        	  public int compare(long[] arr1, long[] arr2) {
				  //return 0;
				  if (arr1[0] < arr2[0]) {
					  return -1;
				  } else if (arr1[1] > arr2[1]) {
					  return 1;
				  } else {
					  return 0;
				  }
	          }
		});
		return array;
	}

