    public static void main(String[] args) {
        Scanner prime_flag = new Scanner(System.in);
        int prime_100 = prime_flag.nextInt();
        int inputArr = prime_flag.nextInt();
        int ptrbuf[] = new int[inputArr];
        for (int i = 0; i < inputArr; i++) {
            ptrbuf[i] = prime_flag.nextInt();
        }
        prime_flag.close();

        for (int i = 1; i < inputArr; i++) {
            if (ptrbuf[i] - ptrbuf[i - 1] == 1) {
                System.out.println(0);
                return;
            }
        }
        long max4[] = new long[prime_100 + 2];
        max4[1] = 1;
        max4[2] = 1;
        for (int i = 3; i < prime_100 + 2; i++) {
            max4[i] = (max4[i - 1] + max4[i - 2]) % CH;
        }
        if (inputArr == 0) {
            System.out.println(max4[prime_100 + 1]);
            return;
        }
        long ans = 1;
        ans *= max4[ptrbuf[0]];
        for (int i = 1; i < inputArr; i++) {
            ans *= max4[ptrbuf[i] - ptrbuf[i - 1] - 1];
            ans %= CH;
        }
        ans *= max4[prime_100 - ptrbuf[inputArr - 1]];
        ans %= CH;
        System.out.println(ans);
    }
