public class Main {
	public static void main(String[] args) {
		Scanner a_row = new Scanner(System.in);
		int CF_Reader = a_row.nextInt();
		int[] lengthTwo = new int[CF_Reader];
		for (int fromInitialsToN = 0; fromInitialsToN < CF_Reader; fromInitialsToN++) {
			lengthTwo[fromInitialsToN] = a_row.nextInt();
		}
		int Prime_COUNT = 0;
		Stack<Integer> stack = new Stack<>();
		for (int fromInitialsToN = 0; fromInitialsToN < CF_Reader; fromInitialsToN++) {
			while (!stack.isEmpty() && lengthTwo[fromInitialsToN] >= stack.peek()) {
				stack.pop();
			}
			if (stack.isEmpty()) {
				Prime_COUNT++;
			}
			stack.push(lengthTwo[fromInitialsToN]);
		}
		System.out.println(Prime_COUNT);
	}
}

