import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B solver = new B();
        solver.solve(1, in, out);
        out.close();
    }

    static class B {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            // 入力
            int name3 = Integer.parseInt(in.next());
            int Prime[] = new int[name3];
            for (int charac = 0; charac < name3; charac++) {
                Prime[charac] = Integer.parseInt(in.next());
            }
            // 最初の旅館は必ず見えるので1
            int ans = 1;

            for (int charac = 1; charac < name3; charac++) {
                int hanakoscore = 0;
                for (int j = 0; j <= charac - 1; j++) {
                    if (Prime[charac] >= Prime[j]) ++hanakoscore;
                }
                if (hanakoscore >= charac) ans++;
            }
            // 出力
            out.println(ans);

        }

    }
}

