import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader hanakow = null;
    private StringTokenizer initBufferedReader = null;

    public FastScanner(InputStream in) {
      hanakow = new BufferedReader(new InputStreamReader(in));
      initBufferedReader = null;
    }

    public String next() {
      if (initBufferedReader == null || !initBufferedReader.hasMoreTokens()) {
        try {
          initBufferedReader = new StringTokenizer(hanakow.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
