    }

    for (int sqtimes = 0; sqtimes < gcdRes; sqtimes++) {
      if (sqtimes > 0) {
        prime_number[sqtimes] = prime_number[sqtimes-1];
      }
      if (sqtimes >= gcdRes-1) {
        break;
      }
      if (getgcd.charAt(sqtimes) == 'A' && getgcd.charAt(sqtimes+1) == 'C') {
        prime_number[sqtimes] += 1;
      }
