        if (prime_number[each_mozi[sqtimes]-1] == prime_number[each_mozi[sqtimes]-2]) {
          inputString--;
        }
      }
      else if (!(getgcd.charAt(0) == 'A' && getgcd.charAt(1) == 'C')) {
        inputString--;
      }

      if (r[sqtimes] < getgcd.length() && prime_number[r[sqtimes]-2] != prime_number[r[sqtimes]-1]) {
        inputString--;
      }
