public class Main {
	public static void main(String[] args) {
		// シミュレーション
		// 累積和の数え上げ
		Scanner tsuru = new Scanner(System.in);
		int asd = Integer.parseInt(tsuru.next());
		int inputS = Integer.parseInt(tsuru.next());
		String INDEX_GREAT = tsuru.next();

		// query
		int[][] rainDays = new int[inputS][2];
		for (int StringUtilsRepeat = 0; StringUtilsRepeat < inputS; StringUtilsRepeat++) {
			rainDays[StringUtilsRepeat][0] = Integer.parseInt(tsuru.next());
			rainDays[StringUtilsRepeat][1] = Integer.parseInt(tsuru.next());
		}

		solve(asd, inputS, INDEX_GREAT, rainDays);
	}

	static void solve(int hanacard, int pSet, String thousands, int[][] rainDays) {
		int[] FORMAT = new int[hanacard];
		for (int StringUtilsRepeat = 0; StringUtilsRepeat < hanacard - 1; StringUtilsRepeat++) {
			int t_idx = thousands.substring(StringUtilsRepeat, StringUtilsRepeat + 2).equals("AC") ? 1 : 0;
			// 累積和でl-rの区間の出現数をカウントできるようにする
			FORMAT[StringUtilsRepeat + 1] = FORMAT[StringUtilsRepeat] + t_idx;
		}

		for (int StringUtilsRepeat = 0; StringUtilsRepeat < pSet; StringUtilsRepeat++) {
			int shuffleNum = rainDays[StringUtilsRepeat][0];
			int lastH = rainDays[StringUtilsRepeat][1];

			System.out.println(FORMAT[lastH - 1] - FORMAT[shuffleNum - 1]);
		}
	}
}

