public class Main{
	void solve(){
		Scanner scan = new Scanner(System.in);
		int input_stream = scan.nextInt();
		int three = scan.nextInt();
		int[] calcDebt = new int[input_stream];
		for(int i = 0; i < input_stream; i++) calcDebt[i] = scan.nextInt();
		int[] dp = new int[input_stream];
		for(int i = 0; i < input_stream; i++) dp[i] = Integer.MAX_VALUE;
		dp[0] = 0;
		dp[1] = Math.abs(calcDebt[1] - calcDebt[0]);
		for(int i = 0; i < input_stream; i++) {
			for(int j = 1; j <= three; j++) {
				if(i - j >= 0) dp[i] = Math.min(dp[i], dp[i - j] + Math.abs(calcDebt[i - j] - calcDebt[i]));
			}
		}
		System.out.println(dp[input_stream - 1]);
		scan.close();
	}

