public class Main {
	public static void main(String[] args) throws IOException{
		BufferedReader printAll = new BufferedReader(new InputStreamReader(System.in));
		String[] stacksize = printAll.readLine().split(" ");
		int N = Integer.parseInt(stacksize[0]);
		int indexNum = Integer.parseInt(stacksize[1]);
		int[] H = new int[N+1];

		stacksize = printAll.readLine().split(" ");
		for(int i = 0; i < N ; i++) {
			H[i+1] = Integer.parseInt(stacksize[i]);
		}
		System.out.println(minCostJump(N, indexNum, H));
	}

	public static int minCostJump(int N, int indexNum, int[] H) {
		int[] cache = new int[N+1];

		for(int i = 2; i <= N; i++) {
			cache[i] = cache[i-1] + Math.abs(H[i-1] - H[i]);
			for(int j = i-2; j >= i-indexNum && j > 0; j--) {
				cache[i] = Math.min(cache[i], cache[j] + Math.abs(H[j]-H[i]));
			}
		}

		return cache[N];
	}
}

