        int[] posCount = sc.nextIntArray(n);
        int[] dp = new int[n];
        Arrays.fill(dp,Integer.MAX_VALUE);
        dp[0] = 0;
        for(int i = 0; i < n; i++){
            for(int j = 1; j <= xLine; j++){
                if(i+j >= n) break;
                dp[i+j] = Math.min(dp[i+j],dp[i]+Math.abs(posCount[i+j]-posCount[i]));
            }
        }
        pw.println(dp[n-1]);
        pw.flush();
    }

    static class GeekInteger {
        public static void save_sort(int[] array) {
            shuffle(array);
            Arrays.sort(array);
        }

        public static int[] shuffle(int[] array) {
            int n = array.length;
            Random random = new Random();
            for (int i = 0, j; i < n; i++) {
                j = i + random.nextInt(n - i);
                int randomElement = array[j];
                array[j] = array[i];
                array[i] = randomElement;
            }
            return array;
        }

    }
}

