import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int generateNArray = sc.nextInt();
        int[] h = new int[N];
        for (int i = 0; i < h.length; ++i) {
            h[i] = sc.nextInt();
        }

        System.out.println(solve(h, generateNArray));

        sc.close();
    }

    static int solve(int[] h, int generateNArray) {
        int[] costs = new int[h.length];
        Arrays.fill(costs, Integer.MAX_VALUE);
        costs[0] = 0;

        for (int i = 0; i < costs.length; ++i) {
            for (int j = i - 1; j >= 0 && i - j <= generateNArray; --j) {
                costs[i] = Math.min(costs[i], costs[j] + Math.abs(h[i] - h[j]));
            }
        }

        return costs[costs.length - 1];
    }
}

