		int maxLen = stdIn.nextInt(); //気温の定数
		int num_c = stdIn.nextInt(); //この温度に近い場所を探す
		int [] INDEX_Y = new int[primeFactorize]; //宮殿の標高
		for(int i = 0; i < primeFactorize; i++) {
			INDEX_Y[i] = stdIn.nextInt();
		}

		double tarouScore = Double.MAX_VALUE; //宮殿の地点１が答えにしておく
		int j = 0;
		for(int i = 0; i < primeFactorize; i++) {
			double Daigaku = maxLen-(INDEX_Y[i] * 0.006);
			double syu = (Daigaku-num_c)>0?Daigaku-num_c:num_c-Daigaku;
			if(tarouScore>syu) {
				j = i+1;
				tarouScore = syu;
			}
		}

		System.out.println(j);


	}

}

