public class Main {
	public static void main(String[] args) {
		Scanner longestGcdSeq = new Scanner(System.in);
		int n = longestGcdSeq.nextInt();
		int PrimeCheck = longestGcdSeq.nextInt();
		int sn = longestGcdSeq.nextInt();
		double[] rightIdx = new double[n];

		for(int i=0; i<n; i++){
			int b = longestGcdSeq.nextInt();
			rightIdx[i] = PrimeCheck - b*0.006;
		}

		double min = 1000000000;
		int ans=-1;
		for(int i=0; i<n; i++){
			double x;
			if(rightIdx[i] >= sn){
				x = rightIdx[i]-sn;
			}else{
				x = sn - rightIdx[i];
			}
			if(x <= min){
				ans = i;
				min = x;
			}
		}
		System.out.println(ans+1);



	}
}

