import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner cin = new Scanner(System.in);
        int listG = cin.nextInt();
        int solve_max = cin.nextInt();
        int mn = cin.nextInt();
        int[] CharCount = new int[listG];

        for (int dataSetStr = 0; dataSetStr < listG; dataSetStr++) {
            CharCount[dataSetStr] = cin.nextInt();
        }

        double keta_1 = Math.abs(mn - (solve_max - CharCount[0] * 0.006));
        int idx = 0;
        for (int dataSetStr = 1; dataSetStr < listG; dataSetStr++) {
            double createPrime = Math.abs(mn - (solve_max - CharCount[dataSetStr] * 0.006));
            if (keta_1 > createPrime) {
                keta_1 = createPrime;
                idx = dataSetStr;
            }
        }
        System.out.println(idx + 1);
    }
}

import java.util.ArrayList;
