import java.util.Scanner;

public class Main {
    public static void main(String[] args){
        Scanner bn = new Scanner(System.in);
        int card3 = bn.nextInt();
        int intNext = bn.nextInt();
        int[][] flg1 = new int[card3][2];
        List<Integer> Q_ans = new ArrayList<>();

        for(int i = 0; i < card3; i++){
            for(int sv = 0; sv < 2; sv++){
                flg1[i][sv] = bn.nextInt();
            }
        }
        for(int i = 0; i < card3; i++) {
            if (flg1[i][1] <= intNext) {
                Q_ans.add(i);
            }
        }
        if (Q_ans.size() == 0){
            System.out.println("TLE");
        }else {
            int checkPrimeNumber = flg1[0][0];
            for (int k : Q_ans) {
                if (flg1[k][0] < checkPrimeNumber) {
                    checkPrimeNumber = flg1[k][0];
                }
            }

            System.out.println(checkPrimeNumber);
        }
    }
}

