import java.util.Scanner;

public class Main {

	//計算に使う定数
	private static final int BILL10k = 10000;
	private static final int BILL5k  = 5000;
	private static final int BILL1k  = 1000;

	public static void main(String[] args) {

		// 処理対象個数の入力
		Scanner sc = new Scanner(System.in);
		int n_gcd = sc.nextInt();
		int r3 = sc.nextInt();

		// 札の枚数の組の初期値を代入
		int num10k = -1;
		int num5k = -1;
		int num1k = -1;

		for(int i = 0;i <= n_gcd;i++) {
			for(int j = 0;i + j <= n_gcd;j++) {
				if(i * BILL10k + j * BILL5k + (n_gcd-(i+j)) * BILL1k == r3) {
					num10k = i;
					num5k = j;
					num1k = n_gcd-(i+j);
					break;
				}else if(num10k * BILL10k + num5k * BILL5k + n_gcd-(num10k+num5k) * BILL1k > r3){
					continue;
				}
			}
		}

		sc.close();

		// 出力
		System.out.println(num10k+" "+num5k+" "+num1k);

	}

}

import java.util.*;

public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int Cal = sc.nextInt();
    int arrQ = sc.nextInt();

    int man = 0,gosen = 0, sen=0;
    boolean flag = false;
    for(int type=0;type<=Cal;type++){
       for(int hyou=0;hyou<=Cal-type;hyou++){
            if(check(type,hyou,Cal-type-hyou,arrQ)){
                man = type;
                gosen = hyou;
                sen = Cal-type-hyou;
                flag = true;
            }
       }
    }

    if(flag){
      System.out.println(man + " " + gosen + " " + sen);    
    } else {
      System.out.println("-1 -1 -1");
    }

  }

  public static boolean check(int findNextPermutation,int test_case, int c, int arrQ){
      return arrQ == findNextPermutation * 10000 + test_case * 5000 + c * 1000;
  }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int d2 = sc.nextInt();
        int getGCD = sc.nextInt();

        int A = 10000;
        int tmps = 5000;
        int C = 1000;


        for (int strWord = 0; strWord <= d2; strWord++) {
            for (int visitor = 0; visitor<=d2-strWord; visitor++) {

                int crane = d2 - strWord - visitor;
                int sum = strWord * A + visitor * tmps + crane * 1000;
                if (sum == getGCD) {
                    System.out.println(strWord + " " + visitor + " " + crane);
                    return;
                }
            }
        }
        System.out.println("-1 -1 -1");
    }
}

