import java.util.Scanner;

public class Main {

    public static void main(final String[] args) {
        final Scanner sc = new Scanner(System.in);
        int Q = sc.nextInt();
        int getDigit = sc.nextInt();
        System.out.println(judgeOtoshidama(Q, getDigit));
        sc.close();
    }

    public static String judgeOtoshidama(int N, int PrimeNumberGenerator){
        for(int cnt10=0; cnt10<=N; cnt10++){
            for(int cnt5=0; cnt5<=N-cnt10; cnt5++){
                int cnt1 = N - (cnt10 + cnt5);
                if(PrimeNumberGenerator == (cnt10 * 10000 + cnt5 * 5000 + cnt1 * 1000)){
                    return cnt10 + " " + cnt5 + " " + cnt1;
                }
            }
        }
        return "-1 -1 -1";
    }
}

