import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        int inputs_numt = Integer.parseInt(sc.next());
        int intVector = Integer.parseInt(sc.next());

        int result = 0;
        for (int i = 1; i <= N; i++) {
            int height = i;
            int getFinishtime = 0;
            while (height > 0) {
                // 整数 n を10で割ると一桁目の数が余りとして出てくる
                // 一桁目が 0 ならば、割り切れるので余りは 0
                getFinishtime += height % 10; // 各桁の合計digSum にこの余りの値を加えてやる。
                // 次の桁に行くために、整数 n を10で割ってやる。そうすると最下位の桁が捨てられる。
                height /= 10;
            }
            if (getFinishtime >= inputs_numt && getFinishtime <= intVector) {
                result += i;
            }
        }
        System.out.println(result);
    }
}

import java.io.*;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, in, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int N = Integer.parseInt(in.next());
            int solveJuice = Integer.parseInt(in.next());
            int B = Integer.parseInt(in.next());

            int sum = 0;
            for (int minval = 1; minval <= N; minval++) {
                int not_prime = minval;
                int digSum = 0;
                while (not_prime > 0) {
                    digSum += not_prime % 10;
                    not_prime /= 10;
                }
                if (digSum >= solveJuice && digSum <= B)
                    sum += minval;
            }
            out.println(sum);
        }

    }
}

