import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int n_nodes = sc.nextInt();
        int b = sc.nextInt();
        int umcnt = 0;

        for (int i = 1; i <= n; i++) {
            int stddev = getSumOfEachDigit(i);
            if (n_nodes <= stddev && stddev <= b) {
                umcnt += i;
            }
        }
        System.out.println(umcnt);
    }

    private static int getSumOfEachDigit(int num) {
        // numが1234の場合
        // len: 4
        int len = String.valueOf(num).length();
        int umcnt = 0;
        // d: 1000
        int d = (int)Math.pow(10, len - 1);
        for (int i = 0; i < len; i++) {
            // nums: [1, 2, 3, 4]
            umcnt += num / d;
            // num: 234
            num %= d;
            // d: 100
            d /= 10;
        }
        return umcnt;
    }
}

