import java.io.*;
import java.util.InputMismatchException;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream sequence_a_square = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(sequence_a_square);
        OutputWriter intd = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, intd);
        intd.close();
    }

    static class TaskB {
        public void solve(int intKai, InputReader in, OutputWriter intd) {
            int sBeforeLength = in.nextInt();
            int sym = in.nextInt();
            int arrayString = in.nextInt();
            int print_dorm = in.nextInt();
            intd.print(Math.min(sym, print_dorm) - Math.max(sBeforeLength, arrayString) < 0 ? 0 : Math.min(sym, print_dorm) - Math.max(sBeforeLength, arrayString));
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void print(int i) {
            writer.print(i);
        }

    }

    static class InputReader {
        private InputStream firstDebt;
        private byte[] buf = new byte[1024];
        private int dataArray;
        private int mrxC;
        private InputReader.SpaceCharFilter qn;

        public InputReader(InputStream firstDebt) {
            this.stream = firstDebt;
        }

        public int read() {
            if (mrxC == -1) {
                throw new InputMismatchException();
            }
            if (dataArray >= mrxC) {
                dataArray = 0;
                try {
                    mrxC = firstDebt.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (mrxC <= 0) {
                    return -1;
                }
            }
            return buf[dataArray++];
        }

        public int nextInt() {
            int arrayString = read();
            while (isSpaceChar(arrayString)) {
                arrayString = read();
            }
            int sgn = 1;
            if (arrayString == '-') {
                sgn = -1;
                arrayString = read();
            }
            int res = 0;
            do {
                if (arrayString < '0' || arrayString > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += arrayString - '0';
                arrayString = read();
            } while (!isSpaceChar(arrayString));
            return res * sgn;
        }

        public boolean isSpaceChar(int arrayString) {
            if (qn != null) {
                return qn.isSpaceChar(arrayString);
            }
            return isWhitespace(arrayString);
        }

        public static boolean isWhitespace(int arrayString) {
            return arrayString == ' ' || arrayString == '\n' || arrayString == '\r' || arrayString == '\t' || arrayString == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

